// Comparison of the web engine against the MATLAB reference vectors
// (generated by matlab/fase*/val_*.m). Used by the tests and the Validation tab.
import { C0, DEFAULT_BEAM, DEFAULT_FACE, DEFAULT_RADAR, faceGeometry, type TaperKind } from '../engine/config';
import { pdSwerling0, radarHorizon, snrConstant, snrReqSwerling1 } from '../engine/radar';
import {
  gasAttenDbKm, kFactor, propagationFactor, rainAttenDbKm, refractivity, seaPermittivity, seaSigma0Db, twoRayGeometry,
} from '../engine/environment';
import { computeWeights } from '../engine/array';
import { azimuthCut, elevationCut } from '../engine/pattern';
import { taper1d } from '../engine/tapers';
import refAntena from './ref_antena.json';
import refRadar from './ref_radar.json';
import refEntorno from './ref_entorno.json';
import refAcopl from './ref_acoplamiento.json';
import { DIPOLE, centerActiveZ, couplingFor, dipoleOverGroundPower, mutualZ, scanGamma } from '../engine/coupling';

export interface Check {
  grupo: string;           // model block
  caso: string;
  metrica: string;
  valor: number;           // measured error (in the given unit)
  unidad: string;
  tol: number;             // accepted tolerance
  nota?: string;
  info?: boolean;          // informational: documented method difference, does not count as a failure
}
export const passes = (c: Check) => Math.abs(c.valor) <= c.tol;
export const failing = (cs: Check[]) => cs.filter(c => !c.info && !passes(c));

/** Overlaid curve for the Validation tab plots. */
export interface Overlay {
  id: string; titulo: string; x: number[]; ref: number[]; web: number[]; xLabel: string; yLabel: string; yRange?: [number, number];
  ref2?: number[];        // second reference (e.g. radarpropfactor alongside the exact one)
}

// ─────────────────────────── antenna ───────────────────────────

const face = { ...DEFAULT_FACE };
const g = faceGeometry(face);
const none = new Uint8Array(g.N);

const maxAbs = (a: ArrayLike<number>, b: ArrayLike<number>, mask?: (i: number) => boolean) => {
  let m = 0;
  for (let i = 0; i < a.length; i++) if ((!mask || mask(i)) && Number.isFinite(a[i]) && Number.isFinite(b[i])) m = Math.max(m, Math.abs(a[i] - b[i]));
  return m;
};

export function antennaChecks(): { checks: Check[]; overlays: Overlay[] } {
  const checks: Check[] = [], overlays: Overlay[] = [];
  const t = taper1d('taylor', g.Nx, 35, 5), c = taper1d('chebyshev', g.Nx, 30, 0);
  const mx = (v: number[]) => Math.max(...v);
  const tRef = refAntena.taylor80.map(x => x / mx(refAntena.taylor80)), cRef = refAntena.cheb80.map(x => x / mx(refAntena.cheb80));
  checks.push({ grupo: 'Antena', caso: 'Taylor 35 dB, n̄ = 5 (80)', metrica: 'pesos frente a taylorwin', valor: maxAbs(t, tRef), unidad: '', tol: 1e-3 });
  checks.push({ grupo: 'Antena', caso: 'Chebyshev 30 dB (80)', metrica: 'pesos frente a chebwin', valor: maxAbs(c, cRef), unidad: '', tol: 1e-3 });

  for (const k of refAntena.casos) {
    const beam = { ...DEFAULT_BEAM, taper: k.taper as TaperKind, sllDb: k.sll, nbar: k.nbar || 5, azDeg: k.az, elDeg: k.el, psBits: 0, ttd: false, freqOffsetHz: 0 };
    const w = computeWeights(face, g, beam, none);
    const cut = k.corte === 'az' ? azimuthCut(g, w, face.f0, k.el, 0.1, 90) : elevationCut(g, w, face.f0, 0, 0.1, 90);
    const web = Array.from(cut.gainDbi), ref = k.dbi;
    const center = k.corte === 'az' ? k.az : k.el;
    let pkWeb = -Infinity; for (const v of web) if (v > pkWeb) pkWeb = v;
    const refPk = Math.max(...ref);
    // main lobe (±1.5 HPBW around steering) and sidelobes above −50 dB
    const main = (i: number) => Math.abs(k.ang[i] - center) < 2.5;
    const side = (i: number) => !main(i) && ref[i] > refPk - 50 && Math.abs(k.ang[i]) < 85;
    const nw = web.map(v => v - pkWeb), nr = ref.map(v => v - refPk);
    checks.push({ grupo: 'Antena', caso: k.nombre, metrica: 'ganancia de pico', valor: pkWeb - k.pico, unidad: 'dB', tol: 0.6,
      nota: 'directividad integrada por MATLAB frente a 4π·A_ef/λ²·cos θ' });
    checks.push({ grupo: 'Antena', caso: k.nombre, metrica: 'lóbulo principal (normalizado)', valor: maxAbs(nw, nr, main), unidad: 'dB', tol: 0.1 });
    checks.push({ grupo: 'Antena', caso: k.nombre, metrica: 'lóbulos secundarios > −50 dB (normalizado)', valor: maxAbs(nw, nr, side), unidad: 'dB', tol: 1.0 });
    overlays.push({ id: k.nombre, titulo: `Patrón · ${k.nombre.replace(/_/g, ' ')}`, x: k.ang, ref: nr, web: nw,
      xLabel: k.corte === 'az' ? 'acimut (°)' : 'elevación (°)', yLabel: 'dB rel. pico', yRange: [-70, 2] });
  }
  return { checks, overlays };
}

// ─────────────────────────── radar ───────────────────────────

const db10 = (x: number) => 10 * Math.log10(x);

export function radarChecks(): { checks: Check[]; overlays: Overlay[] } {
  const checks: Check[] = [], overlays: Overlay[] = [];
  const f = C0 / refRadar.meta.lambda;
  for (const c of refRadar.ecuacion) {
    const p = { ...DEFAULT_RADAR, pElemW: c.pt, tauS: c.tau, nPulses: 1, nfDb: c.nf, lossDb: c.loss, rcsM2: c.rcs };
    const K = snrConstant(p, { f, gtDbi: c.gt, grDbi: c.gr, nActive: 1 });
    const err = Math.max(...c.R.map((R: number, i: number) => Math.abs(db10(K / R ** 4) - c.snr[i])));
    checks.push({ grupo: 'Radar', caso: `Pt ${c.pt / 1e3} kW · τ ${c.tau * 1e6} µs · σ ${c.rcs} m²`, metrica: 'SNR frente a radareqsnr', valor: err, unidad: 'dB', tol: 0.01 });
  }
  for (const d of refRadar.deteccion) {
    const e1 = Math.max(...d.pd.map((pd: number, i: number) => Math.abs(db10(snrReqSwerling1(pd, d.pfa)) - d.sw1[i])));
    // Swerling 0: the web Pd (Albersheim) is inverted by bisection to obtain its required SNR
    const snrReq0 = (pd: number) => {
      let lo = -10, hi = 40;
      for (let k = 0; k < 60; k++) { const m = (lo + hi) / 2; if (pdSwerling0(Math.pow(10, m / 10), d.pfa) < pd) lo = m; else hi = m; }
      return (lo + hi) / 2;
    };
    const e0 = Math.max(...d.pd.map((pd: number, i: number) => Math.abs(snrReq0(pd) - d.sw0[i])));
    checks.push({ grupo: 'Detección', caso: `Pfa ${d.pfa.toExponential(0)}`, metrica: 'SNR requerida Swerling 1 frente a detectability', valor: e1, unidad: 'dB', tol: 0.05 });
    checks.push({ grupo: 'Detección', caso: `Pfa ${d.pfa.toExponential(0)}`, metrica: 'SNR requerida Swerling 0 (Albersheim) frente a detectability', valor: e0, unidad: 'dB', tol: 0.3,
      nota: 'Albersheim es una aproximación (±0,2 dB según su autor)' });
    if (d.pfa === 1e-6) overlays.push({ id: 'det', titulo: 'SNR requerida · Pfa = 1e-6 (Swerling 1)', x: d.pd.map((x: number) => 100 * x), ref: d.sw1,
      web: d.pd.map((pd: number) => db10(snrReqSwerling1(pd, d.pfa))), xLabel: 'Pd (%)', yLabel: 'SNR (dB)' });
  }
  const h = refRadar.horizonte;
  const eh = Math.max(...h.h.map((hh: number, i: number) => Math.abs(radarHorizon(hh, 0) - h.R[i]) / h.R[i]));
  checks.push({ grupo: 'Radar', caso: 'antena 5–40 m, k = 4/3', metrica: 'horizonte frente a horizonrange (relativo)', valor: 100 * eh, unidad: '%', tol: 0.1 });
  return { checks, overlays };
}

// ─────────────────────────── environment ───────────────────────────

/** Ground range from slant range (law of cosines on a spherical earth). */
function groundRange(R: number, h1: number, h2: number, Re: number) {
  const a = Re + h1, b = Re + h2;
  const c = (a * a + b * b - R * R) / (2 * a * b);
  return Re * Math.acos(Math.min(1, c));
}

export function envChecks(): { checks: Check[]; overlays: Overlay[] } {
  const checks: Check[] = [], overlays: Overlay[] = [];
  const E = refEntorno, f = E.meta.f, lam = C0 / f, Re = E.meta.Re;

  const ep = seaPermittivity(f);
  checks.push({ grupo: 'Entorno', caso: 'agua de mar 20 °C, 35 ‰', metrica: 'permitividad ε′ frente a ITU-R P.527', valor: 100 * (ep.re - E.permitividad.re) / E.permitividad.re, unidad: '%', tol: 5 });
  checks.push({ grupo: 'Entorno', caso: 'agua de mar 20 °C, 35 ‰', metrica: 'permitividad ε″ frente a ITU-R P.527', valor: 100 * (ep.im + E.permitividad.im) / -E.permitividad.im, unidad: '%', tol: 10 });

  // propagation factor with MATLAB's permittivity, to isolate the two-ray geometry
  const epsRef = { re: E.permitividad.re, im: -E.permitividad.im };
  const webF = (R: number, hr: number, ht: number, pol: string, sh: number) => {
    const geo = twoRayGeometry(hr, ht, groundRange(R, hr, ht, Re), Re);
    return 20 * Math.log10(Math.max(propagationFactor(geo, lam, 4 * sh, epsRef, pol as 'H' | 'V', () => 1), 1e-6));
  };
  const errors = (ref: number[], web: number[]) => {
    const lin = (x: number) => Math.pow(10, x / 20);
    let eLin = 0, eDb = 0;
    ref.forEach((r, i) => {
      eLin = Math.max(eLin, Math.abs(lin(web[i]) - lin(r)));
      if (r > -10) eDb = Math.max(eDb, Math.abs(web[i] - r));
    });
    return { eLin, eDb };
  };
  for (const c of E.exacto) {
    const web = c.R.map((R: number) => webF(R, c.hr, c.ht, c.pol, c.sigmaH));
    const { eLin, eDb } = errors(c.FdB, web);
    const caso = `antena ${c.hr} m · blanco ${c.ht} m · ${c.pol} · σh ${c.sigmaH} m`;
    // with a high target the lobes are very dense (phase of hundreds of rad): the closed-form parabolic
    // geometry (reduced heights h − d²/2ae) leaves a relative phase error of ~1e-3 versus Fermat
    const dense = c.ht >= 1000;
    const nota = dense ? 'lóbulos muy densos: error de fase relativo ~1e-3 de la geometría parabólica cerrada' : undefined;
    checks.push({ grupo: 'Propagación', caso, metrica: 'F (lineal) frente a dos rayos exacto (Fermat)', valor: eLin, unidad: '', tol: dense ? 0.1 : 0.05, nota });
    checks.push({ grupo: 'Propagación', caso, metrica: 'F fuera de los nulos (F > −10 dB)', valor: eDb, unidad: 'dB', tol: dense ? 2 : 0.5, nota });
    overlays.push({ id: `ex${c.ht}${c.pol}${c.sigmaH}`, titulo: `Factor de propagación · ${caso}`, x: c.R.map((r: number) => r / 1e3), ref: c.FdB, web,
      xLabel: 'distancia (km)', yLabel: 'F (dB)', yRange: [-40, 10] });
  }
  // radarpropfactor (Blake) uses the far-target path difference Δ = 2·h·sin θd: this measures how far it
  // departs from exact two-ray (informational) and that the web does match the exact one in those same cases
  for (const c of E.blake) {
    const web = c.R.map((R: number) => webF(R, c.hr, c.ht, c.pol, c.sigmaH));
    const vsExact = errors(c.exactoFdB, web).eLin;
    const matlabVsExact = errors(c.exactoFdB, c.FdB).eLin;
    const caso = `antena ${c.hr} m · blanco ${c.ht} m (radarpropfactor)`;
    checks.push({ grupo: 'Propagación', caso, metrica: 'web frente a dos rayos exacto', valor: vsExact, unidad: '', tol: c.ht >= 1000 ? 0.15 : 0.05,
      nota: c.ht >= 1000 ? 'lóbulos muy densos: error de fase relativo ~1e-3 de la geometría parabólica cerrada' : undefined });
    checks.push({ grupo: 'Propagación', caso, metrica: 'radarpropfactor frente a dos rayos exacto', valor: matlabVsExact, unidad: '', tol: 0.1, info: true,
      nota: 'radarpropfactor usa Blake (Δ = 2·h·sen θd, blanco lejano y alto: con el blanco bajo la antena subestima Δ ≈ 35 %) y, cerca del horizonte, la región intermedia y de difracción, que la web no modela' });
    overlays.push({ id: `bl${c.ht}`, titulo: `Exacto frente a radarpropfactor · antena ${c.hr} m · blanco ${c.ht} m`, x: c.R.map((r: number) => r / 1e3), ref: c.exactoFdB, web,
      ref2: c.FdB, xLabel: 'distancia (km)', yLabel: 'F (dB)', yRange: [-40, 10] });
  }

  for (const s of E.mar) {
    const web = s.graz.map((gz: number) => seaSigma0Db(gz, f, s.ss, s.pol as 'H' | 'V'));
    const err = Math.max(...web.map((v: number, i: number) => Math.abs(v - s.s0dB[i])));
    checks.push({ grupo: 'Clutter', caso: `mar ${s.ss} · ${s.pol}${s.pol}`, metrica: 'σ⁰ NRL frente a seareflectivity', valor: err, unidad: 'dB', tol: 0.05 });
    if (s.ss === 4) overlays.push({ id: `mar${s.pol}`, titulo: `σ⁰ del mar · estado 4 · ${s.pol}${s.pol}`, x: s.graz.map(Math.log10), ref: s.s0dB, web,
      xLabel: 'log₁₀ rasante (°)', yLabel: 'σ⁰ (dB)' });
  }

  for (const gc of E.gases) {
    const gw = gasAttenDbKm(f, gc.T, gc.P, gc.rho);
    checks.push({ grupo: 'Atenuación', caso: `${gc.T} °C · ${gc.rho} g/m³`, metrica: 'gases frente a gaspl (relativo)', valor: 100 * (gw.o2 + gw.h2o - gc.dBkm) / gc.dBkm, unidad: '%', tol: 2 });
  }
  for (const r of E.lluvia) {
    const err = Math.max(...r.R.map((rr: number, i: number) => Math.abs(rainAttenDbKm(f, rr, r.pol as 'H' | 'V') - r.dBkm[i]) / r.dBkm[i]));
    checks.push({ grupo: 'Atenuación', caso: `lluvia 1–50 mm/h · ${r.pol}`, metrica: 'atenuación específica γ frente a rainpl (relativo)', valor: 100 * err, unidad: '%', tol: 1 });
  }

  // standard atmosphere: 15 °C, 1013.25 hPa, 7.5 g/m³ (RH ≈ 58.5 %)
  const N = refractivity(15, 1013.25, 58.5);
  checks.push({ grupo: 'Refracción', caso: 'atmósfera estándar', metrica: 'refractividad Ns frente a refractiveidx', valor: N - E.refraccion.Nstd, unidad: 'N', tol: 5 });
  const ek = Math.max(...E.refraccion.ns.map((ns: number, i: number) => Math.abs(kFactor(ns).k - E.refraccion.k[i]) / E.refraccion.k[i]));
  checks.push({ grupo: 'Refracción', caso: 'Ns 280–380', metrica: 'factor k frente a effearthradius (relativo)', valor: 100 * ek, unidad: '%', tol: 10, info: true,
    nota: 'gradiente del primer km (web) frente a radio efectivo promediado en el trayecto (MATLAB)' });
  return { checks, overlays };
}

// ─────────────────────────── mutual coupling ───────────────────────────

export function couplingChecks(): { checks: Check[]; overlays: Overlay[] } {
  const checks: Check[] = [], overlays: Overlay[] = [];
  const A = refAcopl, lam = A.meta.lambda, k = 2 * Math.PI / lam, L = DIPOLE.lengthL * lam, a = DIPOLE.radiusL * lam;
  // induced EMF kernel versus MoM Z (3×3 in free space): documented method difference
  const c = 4;
  for (const [m, name] of [[4, 'propia'], [1, 'colineal λ/2'], [3, 'lado a lado λ/2'], [0, 'diagonal']] as [number, string][]) {
    const dx = Math.abs(A.x[m] - A.x[c]), dy = Math.abs(A.y[m] - A.y[c]);
    const z = m === c ? mutualZ(k, L, 0, a) : mutualZ(k, L, dx, dy || 1e-9);
    const zr = A.Zre[c][m], zi = A.Zim[c][m];
    checks.push({ grupo: 'Acoplamiento', caso: `dipolos 0,45λ · ${name}`, metrica: 'Z de FEM inducida frente a MoM (relativo)',
      valor: 100 * Math.hypot(z[0] - zr, z[1] - zi) / Math.hypot(zr, zi), unidad: '%', tol: 10, info: true,
      nota: 'la FEM inducida supone corriente sinusoidal; el MoM resuelve la corriente real. Se usa la FEM en el motor por coherencia energética con el diagrama de elemento' });
  }
  // energy consistency (Hannan) and active |Γ| with both kernels
  const g = faceGeometry(DEFAULT_FACE), f = DEFAULT_FACE.f0;
  const { m, zRef } = couplingFor(g, f);
  const ones = new Float64Array(g.N).fill(1);
  let eH = 0;
  for (const ang of [15, 30, 45, 60]) {
    const s = Math.sin(ang * Math.PI / 180);
    for (const [u, v] of [[s, 0], [0, s]]) {
      const z = centerActiveZ(g, m, ones, u, v);
      eH = Math.max(eH, Math.abs(z[0] / zRef[0] / (dipoleOverGroundPower(u, v) / Math.cos(ang * Math.PI / 180)) - 1));
    }
  }
  checks.push({ grupo: 'Acoplamiento', caso: 'array 80×80, elemento central, 15–60°', metrica: 'R_a(θ)/R_a(0) frente a P_elem(θ)/cos θ (Hannan)', valor: 100 * eH, unidad: '%', tol: 1 });
  const e = scanGamma(g, f, 70, 2), mm = scanGamma(g, f, 70, 2, 'mom');
  const eE = Math.max(...e.gE.map((x, i) => Math.abs(x - mm.gE[i]))), eHp = Math.max(...e.gH.map((x, i) => Math.abs(x - mm.gH[i])));
  checks.push({ grupo: 'Acoplamiento', caso: 'array 80×80, plano E, 0–70°', metrica: '|Γ| activo: FEM inducida frente a núcleo de MoM', valor: eE, unidad: '', tol: 0.03 });
  checks.push({ grupo: 'Acoplamiento', caso: 'array 80×80, plano H, 0–70°', metrica: '|Γ| activo: FEM inducida frente a núcleo de MoM', valor: eHp, unidad: '', tol: 0.03 });
  overlays.push({ id: 'gamE', titulo: '|Γ| activo frente al barrido · plano E', x: e.ang, ref: mm.gE, web: e.gE, xLabel: 'ángulo de barrido (°)', yLabel: '|Γ|', yRange: [0, 1] });
  overlays.push({ id: 'gamH', titulo: '|Γ| activo frente al barrido · plano H', x: e.ang, ref: mm.gH, web: e.gH, xLabel: 'ángulo de barrido (°)', yLabel: '|Γ|', yRange: [0, 1] });
  return { checks, overlays };
}

export function allChecks() {
  const parts = [antennaChecks(), couplingChecks(), radarChecks(), envChecks()];
  return { checks: parts.flatMap(p => p.checks), overlays: parts.flatMap(p => p.overlays) };
}
